const WALK_AUDIO={"voice":"af_heart","speed":0.9,"lines":{"intro":{"t":"This is the scatterplot data sheet. It records when a behavior happens across the school day, so the team can see the pattern. Here is how to fill it out.","d":9.675,"a":"data:audio/mpeg;base64,"},"head":{"t":"At the top, write your name as the observer, and the setting. The student, the target behavior, the dates, and the sheet number are printed for you.","d":8.949,"a":"data:audio/mpeg;base64,"},"defs":{"t":"Below that is the definition of the behavior, with an example and a non-example. Read it before you start. Only what fits the definition is marked.","d":9.867,"a":"data:audio/mpeg;base64,"},"grid":{"t":"The grid is the school day. Each row is one interval of time, with the activity printed beside it. Each column is one day. Write the date at the top of each day's column.","d":11.488,"a":"data:audio/mpeg;base64,"},"low":{"t":"At the end of each interval, mark its cell. If the behavior happened once, draw a slash through the cell.","d":6.197,"a":"data:audio/mpeg;base64,"},"high":{"t":"If it happened two or more times, shade the whole cell. The cutoff is printed in the legend at the bottom of your sheet; use the number printed there.","d":9.013,"a":"data:audio/mpeg;base64,"},"blank":{"t":"If you watched the interval and the behavior did not happen, leave the cell blank. A blank means you watched, and there was none.","d":7.307,"a":"data:audio/mpeg;base64,"},"count":{"t":"At the end of each interval, write the number of times the behavior happened in its cell. Leave the cell blank when you watched and there was none. The legend at the bottom tells the team which numbers count as high rate; you only write the number.","d":14.645,"a":"data:audio/mpeg;base64,"},"mark":{"t":"At the end of each interval, mark its cell. If the behavior happened in that interval, once or many times, shade the whole cell. There is no slash on this sheet; a cell is either blank or shaded.","d":12.064,"a":"data:audio/mpeg;base64,"},"blank1":{"t":"If you watched the interval and the behavior did not happen, leave the cell blank. A blank means you watched, and there was none. The legend at the bottom of your sheet shows both marks.","d":10.933,"a":"data:audio/mpeg;base64,"},"x":{"t":"If you did not observe the student during an interval, because they were pulled out, at lunch in another room, or absent, write an X in that cell. For a whole day, write an X at the top of the day's column. An X is left out of every count.","d":15.072,"a":"data:audio/mpeg;base64,"},"codes":{"t":"If your sheet has a code key, write the code letter in the marked cell. If the activity in an interval was not the one printed, write what it was.","d":8.693,"a":"data:audio/mpeg;base64,"},"daily":{"t":"At the end of each day, initial that day's line on the back of the sheet, and note anything unusual, like a fire drill or a substitute. The totals at the bottom are for the behavior analyst; you can leave them.","d":13.557,"a":"data:audio/mpeg;base64,"},"sample":{"t":"A sheet marked SAMPLE may be attached. It shows what a filled-in sheet looks like. It is not the student's data: do not count it, and do not copy from it. Mark the blank sheet.","d":11.083,"a":"data:audio/mpeg;base64,"},"outro":{"t":"Return the sheet to the behavior analyst at the end of the week. Thank you for marking it carefully.","d":5.749,"a":"data:audio/mpeg;base64,"}}};
